const HADISLER=[["Ameller niyetlere göredir; herkese ancak niyet ettiği şey vardır.", "Buhârî, Müslim (Hz. Ömer)"], ["Sizden biriniz, kendisi için istediğini kardeşi için de istemedikçe gerçek anlamda iman etmiş olmaz.", "Buhârî, Müslim (Enes b. Mâlik)"], ["Allah'a ve âhiret gününe iman eden ya hayır söylesin ya da sussun.", "Buhârî, Müslim (Ebû Hüreyre)"], ["Kişinin kendisini ilgilendirmeyen şeyleri bırakması, onun Müslümanlığının güzelliğindendir.", "Tirmizî (Ebû Hüreyre)"], ["Bir adam “Bana öğüt ver” dedi. Peygamberimiz “Öfkelenme” buyurdu; adam tekrar sorunca yine “Öfkelenme” dedi.", "Buhârî (Ebû Hüreyre)"], ["Nerede olursan ol Allah'tan sakın (takvâ üzere ol). Kötülüğün ardından bir iyilik yap ki onu silsin. İnsanlara güzel ahlakla davran.", "Tirmizî (Ebû Zer)"], ["Din samimiyettir (nasihattir).", "Müslim (Temîm ed-Dârî)"], ["Kolaylaştırın, zorlaştırmayın; müjdeleyin, nefret ettirmeyin.", "Buhârî, Müslim (Enes b. Mâlik)"], ["Müslüman, dilinden ve elinden Müslümanların güvende olduğu kimsedir.", "Buhârî, Müslim (Abdullah b. Amr)"], ["Sizin en hayırlınız Kur'an'ı öğrenen ve öğretendir.", "Buhârî (Hz. Osman)"], ["Temizlik imanın yarısıdır.", "Müslim (Ebû Mâlik el-Eş'arî)"], ["Bir hayra vesile olan, onu yapan gibi sevap kazanır.", "Müslim (Ebû Mes'ûd el-Ensârî)"], ["Kardeşine gülümsemen sadakadır.", "Tirmizî (Ebû Zer)"], ["Allah katında amellerin en sevimlisi, az da olsa devamlı olanıdır.", "Buhârî, Müslim (Hz. Âişe)"], ["Güçlü kimse güreşte rakibini yenen değil, öfkelendiğinde kendine hâkim olandır.", "Buhârî, Müslim (Ebû Hüreyre)"], ["İnsanlara merhamet etmeyene Allah merhamet etmez.", "Buhârî, Müslim (Cerîr b. Abdullah)"], ["Hayâ imandandır.", "Buhârî, Müslim (Abdullah b. Ömer)"], ["Mü'minlerin iman bakımından en olgunu, ahlakı en güzel olanıdır.", "Ebû Dâvûd, Tirmizî (Ebû Hüreyre)"], ["Sizin en hayırlınız, ailesine karşı en hayırlı olanınızdır.", "Tirmizî (Hz. Âişe)"], ["Allah sizin dış görünüşünüze ve mallarınıza bakmaz; kalplerinize ve amellerinize bakar.", "Müslim (Ebû Hüreyre)"], ["İki nimet vardır ki insanların çoğu onların kıymetini bilmez: sağlık ve boş vakit.", "Buhârî (İbn Abbâs)"], ["Beş şey gelmeden önce beş şeyin kıymetini bil: yaşlılıktan önce gençliğin, hastalıktan önce sağlığın, yoksulluktan önce varlığın, meşguliyetten önce boş vaktin, ölümden önce hayatın.", "Hâkim, el-Müstedrek (İbn Abbâs)"], ["Birbirinize hediye verin ki birbirinizi sevesiniz.", "Buhârî, el-Edebü'l-müfred (Ebû Hüreyre)"], ["Sadaka malı eksiltmez.", "Müslim (Ebû Hüreyre)"], ["Dua ibadetin ta kendisidir.", "Ebû Dâvûd, Tirmizî (Nu'mân b. Beşîr)"], ["Allah'a ve âhiret gününe iman eden komşusuna iyilik etsin.", "Buhârî, Müslim (Ebû Hüreyre)"], ["Kul, kardeşinin yardımında olduğu sürece Allah da onun yardımındadır.", "Müslim (Ebû Hüreyre)"], ["Kim ilim öğrenmek için bir yola girerse, Allah ona cennete giden yolu kolaylaştırır.", "Müslim (Ebû Hüreyre)"], ["Mü'minler birbirlerine karşı, parçaları birbirini tutan bir bina gibidir.", "Buhârî, Müslim (Ebû Mûsâ el-Eş'arî)"], ["Helal de haram da bellidir; ikisinin arasında şüpheli şeyler vardır. Şüpheliden sakınan dinini ve onurunu korumuş olur.", "Buhârî, Müslim (Nu'mân b. Beşîr)"], ["Seni şüpheye düşüreni bırak, şüphe vermeyene yönel.", "Tirmizî, Nesâî (Hz. Hasan)"], ["İnsanlara teşekkür etmeyen Allah'a da şükretmez.", "Ebû Dâvûd, Tirmizî (Ebû Hüreyre)"], ["Rabbin rızası anne babanın rızasında, Rabbin öfkesi de anne babanın öfkesindedir.", "Tirmizî (Abdullah b. Amr)"], ["Selamı yayın, yemek yedirin, insanlar uyurken gece namaz kılın; esenlikle cennete girersiniz.", "Tirmizî, İbn Mâce (Abdullah b. Selâm)"], ["Kulun Rabbine en yakın olduğu an secde hâlidir; secdede duayı çoğaltın.", "Müslim (Ebû Hüreyre)"], ["İki söz vardır ki dile hafif, mizanda ağır, Rahmân'a sevimlidir: Sübhânallâhi ve bihamdihî, sübhânallâhi'l-azîm.", "Buhârî, Müslim (Ebû Hüreyre)"], ["Kim bana bir kez salavat getirirse, Allah ona on kez rahmet eder.", "Müslim (Ebû Hüreyre)"], ["Allah'a yemin ederim ki ben günde yetmiş defadan fazla Allah'tan bağışlanma diler ve O'na tövbe ederim.", "Buhârî (Ebû Hüreyre)"], ["Allah'ın doksan dokuz ismi vardır; kim onları belleyip (anlayıp) korursa cennete girer.", "Buhârî, Müslim (Ebû Hüreyre)"], ["Ben ve yetimi gözetip koruyan kimse cennette şöyle yan yanayız, diyerek işaret ve orta parmaklarını birleştirdi.", "Buhârî (Sehl b. Sa'd)"], ["Bir Müslüman bir ağaç diker ya da ekin eker de ondan bir insan, kuş veya hayvan yerse, bu onun için sadaka olur.", "Buhârî, Müslim (Enes b. Mâlik)"], ["Oruç bir kalkandır.", "Buhârî, Müslim (Ebû Hüreyre)"], ["Ameller pazartesi ve perşembe günleri arz edilir; amelimin oruçluyken arz edilmesini isterim.", "Tirmizî (Ebû Hüreyre)"], ["Kim inanarak ve karşılığını Allah'tan umarak Ramazan orucunu tutarsa geçmiş günahları bağışlanır.", "Buhârî, Müslim (Ebû Hüreyre)"]];
